<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { api } from '../platform';
import { type Row, forumCategories, resourceCategories, statusNames, exchangeNames, formatTime } from '../../../shared/domain';
import { useRequestScope } from '../../../shared/useRequestScope';
const props = defineProps<{ mode: 'forum' | 'resources'; user: Row | null }>();
const emit = defineEmits<{ (event: 'join'): void }>();
const rows = ref<Row[]>([]), mine = ref<Row[]>([]), exchanges = ref<Row[]>([]), replies = ref<Row[]>([]), selected = ref<Row>({}), form = ref<Row>({});
const tab = ref('public'), screen = ref(''), filter = ref('全部'), search = ref(''), replyContent = ref(''), busy = ref(false), error = ref('');
const forum = computed(() => props.mode === 'forum');
const categories = computed(() => forum.value ? forumCategories : resourceCategories);
const visible = computed(() => (tab.value === 'mine' ? mine.value : rows.value).filter(r => (filter.value === '全部' || filter.value === r.category) && [r.title, r.content, r.offering, r.seeking, r.district].join(' ').includes(search.value)));
const availability: Record<string, string> = { available: '可交换', reserved: '交换中', exchanged: '已完成交换', closed: '已关闭' };
const loading = ref(false);
let generation = 0, detailGeneration = 0;
const scope = useRequestScope();
onUnmounted(() => { ++generation; });
async function load() {
  const version = ++generation;loading.value = true;error.value = '';
  try { const data = await api(forum.value ? '/forum/topics' : '/resources'); if (version !== generation) return; rows.value = data;
    if (props.user) { const data = await api(forum.value ? '/my/forum' : '/my/resources'); if (version !== generation) return; mine.value = data; }
    if (!forum.value && props.user) { const data = await api('/my/exchanges'); if (version !== generation) return; exchanges.value = data; }
  } catch (e) { if (version === generation) error.value = (e as Error).message; }
finally { if (version === generation) loading.value = false; } }
function member() { if (!props.user || props.user.status !== 'approved') { emit('join'); return false; } return true; }
function create() { if (!member()) return; screen.value = 'create'; error.value = ''; form.value = forum.value ? { title: '', content: '', category: forumCategories[0] } : { title: '', category: resourceCategories[0], offering: '', seeking: '', district: props.user?.district || '', contact: '' }; }
async function detail(row: Row) { const current = scope.capture(); selected.value = row; replies.value = []; replyContent.value = ''; screen.value = 'detail'; error.value = ''; if (forum.value) try { const data = await api('/forum/topics/' + row.id); if (!current() || selected.value.id !== row.id) return;selected.value = data.topic; replies.value = data.replies; } catch (e) { error.value = (e as Error).message; } }
async function act(action: () => Promise<any>, text: string, keep = false) {
  if (busy.value) return;const current = scope.capture(), id = selected.value.id;busy.value = true;error.value = '';
  try { await action();if (!current()) return;if (!keep) screen.value = '';uni.showToast({ title: text, icon: 'none' });await load();if (current() && keep && selected.value.id === id) await detail(selected.value); }
  catch(e) { if (current()) error.value = (e as Error).message; }finally { if (current()) busy.value = false; }
}
function choose(event: any) { form.value.category = categories.value[Number(event.detail.value)]; }
function confirm(path: string, body: Row | undefined, content: string) { const current = scope.capture();uni.showModal({ title: '请确认', content, success: result => { if (result.confirm && current()) act(() => api(path, 'POST', body), '操作已完成'); } }); }
function exchange(row: Row, action: string) { confirm('/exchanges/' + row.id + '/action', { action }, action === 'confirm' ? '请确认自己负责的资源或服务已实际交付，双方确认后才完成。' : action === 'accept' ? '接受后资源将保留给此申请者，其他待处理申请会自动关闭。' : action === 'reject' ? '确认拒绝此次申请？' : '确认取消尚未接受的申请？'); }
watch([() => props.mode, () => props.user?.id, () => props.user?.status, () => props.user?.role], () => { scope.invalidate();++detailGeneration;busy.value = false;selected.value = {};form.value = {};error.value = '';screen.value = '';replies.value = [];replyContent.value = '';++generation; rows.value = []; mine.value = []; exchanges.value = []; screen.value = ''; tab.value = 'public'; filter.value = '全部'; error.value = ''; load(); }, { flush: 'sync' });
onMounted(load);
</script>
<template>
  <view><view v-if="error" class="error">{{ error }}<button v-if="!screen" class="text-button" :disabled="loading" @click="load">重新加载</button></view><view v-if="loading && !screen" class="loading">正在加载…</view><view v-if="!screen"><view class="title">{{ forum ? '聊乡音，话家常' : '互通有无，资源互换' }}</view><view class="intro">{{ forum ? '分享生活经验，让交流不止于一次相聚。' : '你有所长，我有所需。双方确认，温暖互助。' }}</view><button class="primary" @click="create">{{ forum ? '＋ 发起话题' : '＋ 发布交换资源' }}</button><view class="divider"/><view class="pill-row"><text :class="['pill', { active: tab === 'public' }]" @click="tab = 'public'">{{ forum ? '全部话题' : '资源广场' }}</text><text v-if="user" :class="['pill', { active: tab === 'mine' }]" @click="tab = 'mine'">我的发布</text><text v-if="user && !forum" :class="['pill', { active: tab === 'exchanges' }]" @click="tab = 'exchanges'">我的交换</text></view>
    <template v-if="tab !== 'exchanges'"><view class="pill-row"><text v-for="value in ['全部', ...categories]" :key="value" :class="['pill', { active: filter === value }]" @click="filter = value">{{ value }}</text></view><input v-model="search" class="search" placeholder="搜索标题、内容或地区"/><view v-if="!loading && !error && !visible.length" class="empty">{{ forum ? '有故事，一起聊。期待你的第一个话题。' : '分享你能提供的资源，找到需要它的老乡。' }}</view><view v-for="row in visible" :key="row.id" class="panel" @click="detail(row)"><view class="row"><text class="tag">{{ row.category }}</text><text class="muted">{{ tab === 'mine' ? statusNames[row.status] : forum ? row.replyCount + '条回复' : availability[row.availability] }}</text></view><text class="card-title">{{ row.title }}</text><view v-if="forum" class="post-excerpt">{{ row.content }}</view><template v-else><view class="resource-part"><text>我能提供</text><view class="post-excerpt">{{ row.offering }}</view></view><view class="resource-part seek"><text>我需要</text><view class="post-excerpt">{{ row.seeking }}</view></view></template><view v-if="tab === 'mine' && row.reviewNote" class="safe-note">{{ row.reviewNote }}</view><view class="card-actions"><text class="muted">{{ row.authorName }}</text><text class="link">{{ forum ? row.locked ? '已关闭回复' : '参与讨论 →' : '查看交换详情 →' }}</text></view></view></template>
    <template v-else><view v-if="!loading && !error && !exchanges.length" class="empty">暂无交换记录，去资源广场看看吧。</view><view v-for="row in exchanges" :key="row.id" class="panel"><text class="tag">{{ exchangeNames[row.status] }}</text><text class="card-title">{{ row.resourceTitle }}</text><view class="meta">{{ row.ownerName }} ↔ {{ row.requesterName }}</view><view class="prose">{{ row.message }}</view><view class="safe-note">申请者联系：{{ row.contact }}<br/>资源主人联系：{{ row.ownerContact || '未填写' }}</view><view v-if="row.status === 'accepted'" class="notice-line">资源主人{{ row.ownerConfirmed ? '已' : '未' }}确认 · 申请者{{ row.requesterConfirmed ? '已' : '未' }}确认</view><view class="button-row"><template v-if="row.status === 'pending' && row.ownerId === user?.id"><button class="primary small" :disabled="busy" @click="exchange(row, 'accept')">接受交换</button><button class="outline small" :disabled="busy" @click="exchange(row, 'reject')">拒绝申请</button></template><button v-if="row.status === 'pending' && row.requesterId === user?.id" class="outline small" @click="exchange(row, 'cancel')">取消申请</button><button v-if="row.status === 'accepted' && !(row.ownerId === user?.id ? row.ownerConfirmed : row.requesterConfirmed)" class="primary" @click="exchange(row, 'confirm')">确认我已完成交付</button></view></view></template></view>
    <template v-else><button class="detail-back" :disabled="busy" @click="screen = ''; error = ''">← 返回</button><view class="form-page"><template v-if="screen === 'create'"><view class="form-title">{{ forum ? '发起老乡话题' : '发布交换资源' }}</view><view class="field"><text class="field-label">标题（2–80字）</text><input v-model="form.title" maxlength="80"/></view><view class="field"><text class="field-label">分类</text><picker :range="categories" @change="choose"><view class="outline small">{{ form.category }} ▾</view></picker></view><view v-if="forum" class="field"><text class="field-label">话题正文（10–5000字）</text><textarea v-model="form.content" maxlength="5000"/></view><template v-else><view class="field"><text class="field-label">我能提供（5–2000字）</text><textarea v-model="form.offering" maxlength="2000" placeholder="说明资源内容、数量或服务范围"/></view><view class="field"><text class="field-label">我需要（5–2000字）</text><textarea v-model="form.seeking" maxlength="2000" placeholder="希望交换的物品、技能或帮助"/></view><view class="field"><text class="field-label">所在地区</text><input v-model="form.district" maxlength="80"/></view><view class="field"><text class="field-label">联系方式（仅审核会员可见）</text><input v-model="form.contact" maxlength="80"/></view></template><view class="safe-note">请勿在公开正文中填写敏感个人信息，发布内容审核后展示。</view><button class="primary" :disabled="busy" @click="act(() => api(forum ? '/forum/topics' : '/resources', 'POST', form), '已提交审核')">提交审核</button></template>
    <template v-if="screen === 'detail'"><text class="tag">{{ selected.category }}</text><text class="card-title">{{ selected.title }}</text><view class="meta">{{ selected.authorName }} · {{ formatTime(selected.createdAt) }}</view><template v-if="forum"><view class="prose content-text">{{ selected.content }}</view><button v-if="selected.authorId === user?.id && !selected.locked" class="text-button" @click="confirm('/forum/topics/' + selected.id + '/lock', undefined, '确认关闭此话题的回复？')">关闭话题回复</button><view class="section-title">老乡的回复</view><view v-if="!replies.length" class="safe-note">还没有回复，来聊几句吧。</view><view v-for="reply in replies" :key="reply.id" class="reply-item"><view class="row"><text>{{ reply.authorName }}</text><text class="tag">{{ statusNames[reply.status] }}</text></view><view class="prose content-text">{{ reply.content }}</view><view v-if="reply.reviewNote" class="safe-note">{{ reply.reviewNote }}</view></view><view v-if="selected.locked" class="notice-line">话题已关闭回复</view><template v-else-if="selected.status === 'approved'"><view class="field"><text class="field-label">发表回复（2–2000字）</text><textarea v-model="replyContent" maxlength="2000" placeholder="友善交流，认真回应"/></view><button class="primary" :disabled="busy" @click="member() && act(() => api('/forum/topics/' + selected.id + '/replies', 'POST', { content: replyContent }), '回复已提交审核', true)">提交回复</button></template></template><template v-else><view class="section-title">我能提供</view><view class="prose">{{ selected.offering }}</view><view class="section-title">我需要</view><view class="prose">{{ selected.seeking }}</view><view class="meta">{{ selected.district }} · {{ availability[selected.availability] }}</view><view class="notice-line">{{ selected.contact ? '联系：' + selected.contact : user?.status === 'approved' ? '发布者未填写联系方式' : '联系方式仅向审核会员展示' }}</view><view class="button-row"><button v-if="selected.authorId !== user?.id" class="primary" :disabled="selected.status !== 'approved' || selected.availability !== 'available'" @click="member() && (screen = 'request', form = { message: '', contact: '' })">我想交换</button><button v-if="selected.authorId === user?.id && selected.availability === 'available'" class="outline" @click="confirm('/resources/' + selected.id + '/close', undefined, '关闭后将停止接收交换申请。')">关闭资源</button></view></template></template>
    <template v-if="screen === 'request'"><view class="form-title">发起交换申请</view><view class="intro">{{ selected.title }}</view><view class="field"><text class="field-label">你的交换方案（5–1000字）</text><textarea v-model="form.message" maxlength="1000"/></view><view class="field"><text class="field-label">联系方式（仅双方和组织者可见）</text><input v-model="form.contact" maxlength="80"/></view><button class="primary" :disabled="busy" @click="act(() => api('/resources/' + selected.id + '/requests', 'POST', form), '申请已发出')">发送交换申请</button></template></view></template>
  </view>
</template>
<style scoped>
.resource-part{border-left:5rpx solid #83ac9a;padding-left:22rpx;margin-top:25rpx}.resource-part>text{font-size:22rpx;color:#5f907c}.resource-part.seek{border-color:#ceb382}.resource-part.seek>text{color:#a78c5e}.reply-item{border-bottom:1px solid #e5edeb;padding:25rpx 0}
</style>
